using System.Text;
using System.Text.Encodings.Web;
using System.Text.Json;
using System.Text.Json.Serialization;

namespace Shelf.TestData;

public sealed class GroundTruth
{
    /// <summary>Bumped whenever the generated bytes change for the same arguments (it replaces assembly versions and commit hashes in the output).</summary>
    public const int CurrentGeneratorFormat = 1;

    private static readonly JsonSerializerOptions Options = new()
    {
        PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
        WriteIndented = true,
        NewLine = "\n",
        Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping,
    };

    public int Schema { get; init; } = 1;

    public int GeneratorFormat { get; init; } = CurrentGeneratorFormat;

    public int Seed { get; init; }

    public GroundTruthParameters Parameters { get; init; } = new();

    public LibrarySummary Summary { get; init; } = new();

    public List<GroundTruthWork> Works { get; init; } = [];

    public List<GroundTruthRelation> Relations { get; init; } = [];

    public List<GroundTruthFile> Files { get; init; } = [];

    public static GroundTruth Load(string path) =>
        JsonSerializer.Deserialize<GroundTruth>(File.ReadAllBytes(path), Options)
        ?? throw new InvalidDataException($"'{path}' is not a ground truth file.");

    public static string Serialize(object value) => JsonSerializer.Serialize(value, Options);

    public void Write(string path) =>
        File.WriteAllBytes(path, new UTF8Encoding(false).GetBytes(Serialize(this) + "\n"));
}

public sealed class GroundTruthParameters
{
    public int Works { get; init; }

    public int Files { get; init; }

    public int WordsMin { get; init; }

    public int WordsMax { get; init; }

    public string Compression { get; init; } = "stored";
}

public sealed class LibrarySummary
{
    public int Works { get; init; }

    public int Files { get; init; }

    public int SingleFileWorks { get; init; }

    public int TwoFileWorks { get; init; }

    public int ThreeFileWorks { get; init; }

    public int EpubFiles { get; init; }

    public int PdfFiles { get; init; }

    public int ExactDuplicates { get; init; }

    public int SameFormatDuplicates { get; init; }

    public int EditionPairs { get; init; }

    public int HardNegativePairs { get; init; }

    public int SeriesWorks { get; init; }

    /// <summary>Omitted by <c>--plan</c> because nothing has been written.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public long? TotalBytes { get; init; }
}

public sealed class GroundTruthSeries
{
    public string Name { get; init; } = string.Empty;

    public int Index { get; init; }
}

public sealed class GroundTruthWork
{
    public string Key { get; init; } = string.Empty;

    public string Title { get; init; } = string.Empty;

    public List<string> Authors { get; init; } = [];

    public string Language { get; init; } = string.Empty;

    public int Year { get; init; }

    public string? Isbn13 { get; init; }

    public GroundTruthSeries? Series { get; init; }

    public List<string> Files { get; init; } = [];
}

public sealed class GroundTruthRelation
{
    public string Kind { get; init; } = string.Empty;

    public string A { get; init; } = string.Empty;

    public string B { get; init; } = string.Empty;
}

public sealed class GroundTruthEmbedded
{
    public string? Title { get; init; }

    public List<string> Authors { get; init; } = [];

    public string? Isbn13 { get; init; }

    public string? Language { get; init; }
}

public sealed class GroundTruthFile
{
    public string Path { get; init; } = string.Empty;

    public string Work { get; init; } = string.Empty;

    public string Format { get; init; } = string.Empty;

    public string? EpubVersion { get; init; }

    public int? PageCount { get; init; }

    public long Size { get; init; }

    public string Sha256 { get; init; } = string.Empty;

    public string? DuplicateOf { get; init; }

    public string? DuplicateKind { get; init; }

    public List<string> Traits { get; init; } = [];

    public GroundTruthEmbedded Embedded { get; init; } = new();
}
